43:   if (!/^application\/json(?:\s*;|$)/i.test(request.headers.get('content-type') || '') ||
44:       (request.headers.get('content-encoding') || 'identity') !== 'identity') throw invalid();
45:   const length = request.headers.get('content-length');
46:   if (length !== null && (!/^\d+$/.test(length) || Number(length) > 20000)) throw invalid();
47:   if (!request.body) throw invalid();
48:   const reader = request.body.getReader();
49:   let timer;
50:   const deadline = new Promise((_, reject) => { timer = setTimeout(() => { reject(invalid()); void reader.cancel().catch(() => {}); }, 5000); });
51:   try {
52:     let size = 0;
53:     const chunks = [];
54:     while (true) {
55:       const { done, value } = await Promise.race([reader.read(), deadline]);
56:       if (done) break;
57:       size += value.byteLength;
58:       if (size > 20000) throw invalid();
59:       chunks.push(value);
60:     }
61:     const bytes = new Uint8Array(size); let offset = 0;
62:     for (const chunk of chunks) { bytes.set(chunk, offset); offset += chunk.byteLength; }
63:     try { return JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(bytes)); } catch { throw invalid(); }
64:   } finally { clearTimeout(timer); void reader.cancel().catch(() => {}); }
65: }
